{
  "research": [
    {
      "id": "R1",
      "title": "Sensitivity of Passage Retrieval to Conversational Query Reformulation",
      "bullets": [
        "Designed controlled experiments comparing lexical and dense retrieval under query paraphrasing, omitted context, and conversational references using fixed passage collections.",
        "Analyzed retrieval errors by query transformation and passage relevance, distinguishing vocabulary mismatch from failures to resolve context dependent references."
      ]
    },
    {
      "id": "R2",
      "title": "Negation and Lexical Shortcuts in Intent Classification",
      "bullets": [
        "Designed experiments comparing linear and transformer classifiers on intent examples with negation, contrasting random splits with lexical overlap controlled splits.",
        "Analyzed confusion patterns and prediction changes across paired utterances, examining whether classifiers relied on intent keywords despite changes in negation scope."
      ]
    }
  ],
  "publications": [
    {
      "id": "P1",
      "title": "Intent Keywords Under Negation: A Controlled Evaluation of Utterance Classifiers"
    }
  ],
  "work": [],
  "projects": [
    {
      "id": "T1",
      "title": "Comparative Evaluation of Sequence Models for Entity Recognition",
      "bullets": [
        "Implemented token classification pipelines using a conditional random field and a bidirectional recurrent model with consistent preprocessing and label conventions.",
        "Compared entity level precision and recall, inspecting boundary errors, rare entity mentions, and predictions involving tokens absent from training data."
      ]
    },
    {
      "id": "T2",
      "title": "Extractive Summarization with Frequency and Graph Ranking",
      "bullets": [
        "Implemented sentence selection using term frequency scores and graph based ranking, applying identical sentence segmentation and summary length constraints.",
        "Compared summaries using reference overlap and manual content checks, documenting redundancy, missing central claims, and sensitivity to document length."
      ]
    },
    {
      "id": "T3",
      "title": "Cross-Domain Sentiment Classification with Sparse Text Features",
      "bullets": [
        "Implemented logistic regression and naive Bayes sentiment classifiers using word and character features, keeping preprocessing consistent across review domains.",
        "Compared within domain and cross domain performance, examining errors associated with domain specific vocabulary, mixed sentiment, and short reviews."
      ]
    },
    {
      "id": "T4",
      "title": "Topic Discovery in Short Documents",
      "bullets": [
        "Implemented latent Dirichlet allocation and nonnegative matrix factorization pipelines, comparing count and weighted term representations under consistent vocabulary filtering.",
        "Evaluated topic coherence and assignment stability across initializations, inspecting representative documents to identify overlapping themes and preprocessing sensitive topics."
      ]
    }
  ]
}
